# (чтение) 3132.5 НДС импорт и 1251 Кулданов — обороты ANESCOM 2025–2026
for acc in ('3132.5',):
    for r in q('ВЫБРАТЬ Х.Регистратор КАК Р, Х.Период КАК П, Х.СчетДт.Код КАК Дт, Х.СчетКт.Код КАК Кт, Х.Сумма КАК С, Х.Содержание КАК Сод ИЗ РегистрБухгалтерии.{REG} КАК Х ГДЕ Х.Организация.Наименование ПОДОБНО "%ANESCOM%" И (Х.СчетДт.Код = &А ИЛИ Х.СчетКт.Код = &А) УПОРЯДОЧИТЬ ПО Х.Период', А=acc):
        print(' ', acc, str(r['П'])[:10], r['Дт'], r['Кт'], f"{float(r['С']):>14,.2f}", s(r['Р'])[:50], (r['Сод'] or '')[:30])
print('--- 1251 Кулданов: сальдо по документам-основаниям/субконто')
for r in q('ВЫБРАТЬ Т.Субконто1 КАК К, Т.Субконто2 КАК Д, СУММА(Т.СуммаОстатокДт - Т.СуммаОстатокКт) КАК Б ИЗ РегистрБухгалтерии.{REG}.Остатки(&Н, Счет.Код ПОДОБНО "1251%", , Организация.Наименование ПОДОБНО "%ANESCOM%") КАК Т СГРУППИРОВАТЬ ПО Т.Субконто1, Т.Субконто2', Н=datetime.datetime(2026, 10, 27)):
    if 'Кулданов' in s(r['К']) and abs(r['Б'] or 0) > 1: print('  ', s(r['К'])[:30], '|', s(r['Д'])[:60], f"{float(r['Б']):,.2f}")
